\documentclass{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[spanish]{babel}
\usepackage{amssymb}
\usepackage{amsmath}
\usepackage{amsthm}
\newtheorem{definicion}{Definición}
\newtheorem{teorema}{Teorema}
\title{Cuaderno matemático}
\author{Estudiante}
\date{\today}

\begin{document}
\maketitle

\begin{definicion}Un entero es par si tiene la forma $2k$.\end{definicion}
\begin{teorema}La suma de pares es par.\end{teorema}
\begin{proof}Si $a=2m$ y $b=2n$, entonces $a+b=2(m+n)$.\end{proof}
\end{document}
